function words(){const p=pool();v.innerHTML=`<h2>Palabras · ${S.lvl}</h2>${chips()}`+p.map(w=>`<div class="card row" style="align-items:center"><div><b>${w.en}</b><div class="m">${w.es}</div></div><div style="flex:none;text-align:right"><button class="ib" style="background:var(--mint);color:var(--ink)" data-s="${w.en}">🔊</button><div class="m">${"●".repeat(box(w))}${"○".repeat(5-box(w))}</div></div></div>`).join("")}
