  const oldClickRoute=document.querySelector('nav');
  // Patch the original nav dispatcher through a delegated handler that recognizes our page.
  document.addEventListener('click',e=>{const t=e.target.closest('[data-v="progress"]');if(t){e.preventDefault();e.stopImmediatePropagation();go('progress')}},{capture:true});
  // Render the enhanced dashboard once so the new guided-practice card appears immediately.
