/* English Quest module */

/* English Quest interaction and performance polish. No external libraries required. */
(()=>{
  const root=document.documentElement, main=document.querySelector('#v');
  if(!main)return;
  // A single polite live region improves feedback for assistive technology.
  let live=document.querySelector('#eq-live');
  if(!live){live=document.createElement('div');live.id='eq-live';live.className='eq-live';live.setAttribute('aria-live','polite');live.setAttribute('aria-atomic','true');document.body.appendChild(live)}
  // Animate only when the user has not requested reduced motion.
  const reduce=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  let frame=0;
  const animateView=()=>{
    cancelAnimationFrame(frame);
    frame=requestAnimationFrame(()=>{
      if(reduce)return;
      main.classList.remove('view-enter');
      // Force a style boundary only for the small view container, not the full page.
      void main.offsetWidth;
      main.classList.add('view-enter');
    });
  };
  const observe=new MutationObserver(records=>{
    const replaced=records.some(r=>r.type==='childList'&&r.target===main);
    if(replaced){animateView();}
  });
  observe.observe(main,{childList:true});
  // Animate newly rendered cards once; do not run a permanent animation loop.
  const reveal=new MutationObserver(()=>{
    if(reduce)return;
    main.querySelectorAll('.card:not([data-eq-seen]),.game:not([data-eq-seen]),.level-card:not([data-eq-seen]),.metric:not([data-eq-seen])').forEach((el,i)=>{
      el.dataset.eqSeen='1';el.classList.add('eq-reveal');el.style.animationDelay=Math.min(i*28,140)+'ms';
      el.addEventListener('animationend',()=>{el.classList.remove('eq-reveal');el.style.animationDelay=''}, {once:true});
    });
  });
  reveal.observe(main,{childList:true,subtree:true});
  // Gentle haptics on answer selection where supported. Never required for function.
  document.addEventListener('click',e=>{
    const b=e.target.closest('button');
    if(!b||b.disabled||!navigator.vibrate)return;
    if(b.matches('.opt,[data-coach-answer],[data-g],[data-v]')){try{navigator.vibrate(8)}catch(_){}}
  },{passive:true});
  // Keep the viewport stable in app-like use while retaining OS accessibility settings.
  document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')root.classList.add('eq-active')},{passive:true});
  // Expose a tiny helper for concise screen-reader announcements from later features.
  window.eqAnnounce=(message)=>{live.textContent='';requestAnimationFrame(()=>{live.textContent=String(message||'')})};
  // Warn before leaving with unsaved form text only when a future screen uses a draft field.
  window.addEventListener('error',e=>{if(typeof toast==='function'&&e.message)toast('Ocurrió un error inesperado. Puedes volver a Inicio e intentarlo de nuevo.')});
})();

