/* Mastery checks and error notebook: extends the existing course without external libraries. */
(()=>{
  const LEVELS=["A1","A2","B1","B2","C1","C2"];
  S.mastery=S.mastery||{};S.errorLog=S.errorLog||[];
  let active=null;
  const persist=()=>{try{save()}catch(_){try{localStorage.setItem("eq",JSON.stringify(S))}catch(__){}}};
  const recordError=(entry)=>{S.errorLog=S.errorLog||[];S.errorLog.unshift({...entry,id:Date.now()+"-"+Math.random().toString(36).slice(2,7),date:day(),reviewed:false});S.errorLog=S.errorLog.slice(0,100);persist()};
  const oldMark=mark;
  mark=function(w,ok){oldMark(w,ok);if(w&&!ok&&w.en)recordError({kind:"vocab",prompt:w.en,answer:w.es,level:S.lvl||"A1",source:"Práctica de vocabulario"})};
  const oldLearn=learn;
  learn=function(){oldLearn();
    const p=v.querySelector('p.m');
    if(p)p.insertAdjacentHTML('afterend',`<div class="card mastery-intro"><div class="hr"><div><b>🧠 Evaluación y errores</b><div class="m">Comprueba lo que dominas y vuelve a tus fallos.</div></div><button class="btn ghost" data-errors="1">Repasar errores (${(S.errorLog||[]).filter(e=>!e.reviewed).length})</button></div></div>`);
    v.querySelectorAll('.course-level').forEach(section=>{
      const level=section.querySelector('.level')?.textContent?.trim();if(!level)return;
      const units=CU.filter(u=>u.l===level),done=units.filter(u=>S.cs[u.id]).length,ready=done===units.length,mastery=S.mastery[level];
      section.insertAdjacentHTML('beforeend',`<div class="mastery-test"><div class="hr"><div><b>🎯 Evaluación de dominio</b><div class="m">${ready?'10 preguntas · se aprueba con 80 %':'Completa primero las unidades de este nivel'}</div></div><span class="pill">${mastery?mastery.score+'%':'—'}</span></div><button class="btn" data-assess="${level}" ${ready?'':'disabled'}>${mastery?.passed?'Repetir evaluación':'Evaluar '+level}</button>${mastery?`<p class="m">Último resultado: ${mastery.score}% · ${mastery.passed?'nivel superado':'conviene repasar'} · ${mastery.date||''}</p>`:''}</div>`);
    });
  };
  function assessment(level){
    const units=CU.filter(u=>u.l===level),items=shuf(units.flatMap(u=>u.q.map(q=>({unit:u.id,title:u.t,prompt:q[0],answer:q[1],options:shuf(q.slice(1,5)),explanation:q[5]||u.k})))).slice(0,10);
    if(!items.length){toast('Todavía no hay preguntas para este nivel.');return}
    active={level,items,index:0,score:0,misses:[]};nav('learn');$('.fab').style.display='none';renderQuestion();
  }
  function renderQuestion(){
    if(!active)return;const a=active;
    if(a.index>=a.items.length){
      const pct=Math.round(a.score/a.items.length*100),passed=pct>=80,idx=LEVELS.indexOf(a.level),current=LEVELS.indexOf(S.base||'A1');
      S.mastery[a.level]={score:pct,passed,date:day()};
      if(passed&&idx>=current&&idx<LEVELS.length-1)S.base=LEVELS[idx+1];
      persist();if(passed)gain(50,false);
      v.innerHTML=`<div class="card" style="text-align:center"><div class="big">${passed?'🏆':'🧩'}</div><div class="mini-label">EVALUACIÓN ${a.level}</div><h2>${passed?'¡Nivel superado!':'Vamos a reforzarlo'}</h2><div class="assessment-score">${pct}%</div><p>${a.score}/${a.items.length} respuestas correctas</p><p class="m">${passed?'Has alcanzado el umbral de práctica del 80 %. Es una referencia interna, no una certificación oficial.':'Necesitas al menos 80 %. Revisa los errores y vuelve a intentarlo.'}</p><button class="btn" data-v="learn">Volver al mapa de aprendizaje</button><button class="btn ghost" style="margin-top:8px" data-errors="1">Ver mi cuaderno de errores</button></div>`;
      return;
    }
    const q=a.items[a.index];
    v.innerHTML=`<div class="hr"><button class="pill-action" data-v="learn">← Salir</button><span class="pill">${a.level} · ${a.index+1}/${a.items.length}</span></div><div class="progress-track" style="margin-top:14px"><i style="width:${a.index/a.items.length*100}%"></i></div><div class="mini-label" style="margin-top:22px">${q.title}</div><h2 style="line-height:1.4">${q.prompt}</h2><p class="m">Elige una respuesta. Se necesita un 80 % para superar esta evaluación.</p>${q.options.map((option,i)=>`<button class="opt" data-assess-answer="${i}">${option}</button>`).join('')}<div id="assessment-feedback"></div>`;
  }
  function answer(index){if(!active)return;const q=active.items[active.index],choice=q.options[index],ok=choice===q.answer;
    if(ok)active.score++;else{active.misses.push(q);recordError({kind:'grammar',prompt:q.prompt,answer:q.answer,chosen:choice,explanation:q.explanation,level:active.level,source:'Evaluación de dominio'});}
    document.querySelectorAll('[data-assess-answer]').forEach((b,i)=>{b.disabled=true;if(q.options[i]===q.answer)b.classList.add('ok');else if(i===index)b.classList.add('bad')});
    const fb=$('#assessment-feedback');if(fb)fb.innerHTML=`<div class="glass" style="margin-top:14px"><b>${ok?'✓ Correcto':'💡 Respuesta correcta: '+q.answer}</b><p class="m">${q.explanation||''}</p><button class="btn" id="assessment-next">${active.index===active.items.length-1?'Ver resultado':'Siguiente pregunta'}</button></div>`;
    $('#assessment-next').onclick=()=>{active.index++;renderQuestion()};
  }
  function errors(){nav('learn');$('.fab').style.display='none';const list=S.errorLog||[],pending=list.filter(e=>!e.reviewed);
    v.innerHTML=`<div class="hr"><div><div class="mini-label">Tu memoria de aprendizaje</div><h2>Cuaderno de errores</h2></div><span class="pill">${pending.length} pendientes</span></div><p class="m">Los errores no son una nota: son una lista de cosas concretas que puedes volver a practicar.</p>${list.length?list.map(e=>`<div class="card error-entry" style="opacity:${e.reviewed?.65:1}"><div class="hr"><span class="pill">${e.level||'Inglés'}</span><span class="m">${e.reviewed?'Revisado':e.date||''}</span></div><b>${e.prompt||e.question||''}</b><p style="margin:8px 0;color:var(--ok)">Respuesta: ${e.answer||''}</p>${e.chosen?`<p class="m">Tu respuesta: ${e.chosen}</p>`:''}${e.explanation?`<p class="m">${e.explanation}</p>`:''}<div class="hr"><span class="m">${e.source||'Práctica'}</span>${e.reviewed?'':`<button class="btn ghost" data-review-error="${e.id}">Marcar revisado</button>`}</div></div>`).join(''):'<div class="card"><h3>¡Todavía no hay errores guardados!</h3><p class="m">Haz algunas prácticas o evaluaciones y aquí aparecerán los temas que conviene reforzar.</p></div>'}<button class="btn ghost" data-v="learn">Volver a las lecciones</button>`;
  }
  document.addEventListener('click',e=>{
    const t=e.target.closest('[data-assess],[data-assess-answer],[data-errors],[data-review-error]');if(!t)return;
    if(t.dataset.assess){e.preventDefault();e.stopImmediatePropagation();assessment(t.dataset.assess)}
    else if(t.dataset.assessAnswer!==undefined){e.preventDefault();e.stopImmediatePropagation();answer(Number(t.dataset.assessAnswer))}
    else if(t.dataset.errors){e.preventDefault();e.stopImmediatePropagation();errors()}
    else if(t.dataset.reviewError){e.preventDefault();e.stopImmediatePropagation();const item=(S.errorLog||[]).find(x=>String(x.id)===t.dataset.reviewError);if(item)item.reviewed=true;persist();errors()}
  },true);
})();

