/* Adaptive practice v1: prioritizes weak topics and due review, with local-only skill analytics. */
(()=>{
  const $=s=>document.querySelector(s), levels=['A1','A2','B1','B2','C1','C2'];
  S.skillStats=S.skillStats||{}; S.adaptiveStats=S.adaptiveStats||{sessions:0,answered:0,correct:0}; S.review=S.review||{}; S.errorLog=S.errorLog||[];
  let run=null;
  const saveAdaptive=()=>{try{save()}catch(e){try{localStorage.setItem('eq',JSON.stringify(S))}catch(_){}}};
  const todayKey=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
  const plusDays=(n)=>{const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
  const skillOf=u=>{const t=(u.t+' '+(u.x||[]).join(' ')).toLowerCase();if(/pragm|iron|tone|subtext|argument|síntesis|retórica|registro|conector|cohes|discourse|hedging|academic/.test(t))return 'Comunicación';if(/vocab|palabra|collocation|idiom|phrasal|word|lexic|prefix|suffix/.test(t))return 'Vocabulario';if(/reading|lectura|text|story|historia|listening|escucha|dictation|dictado/.test(t))return 'Comprensión';return 'Gramática'};
  const allQuestions=()=>CU.flatMap(u=>(u.q||[]).map(q=>({level:u.l,unit:u.id,title:u.t,skill:skillOf(u),prompt:q[0],answer:q[1],options:shuf([q[1],q[2],q[3],q[4]]),explanation:q[5]||u.k||'',weight:((S.errorLog||[]).some(e=>!e.reviewed&&(e.prompt===q[0]||e.question===q[0]))?5:0)+(!S.cs[u.id]?2:0)+(u.l===(S.base||'A1')?2:0)+Math.max(0,3-Number((S.skillStats[skillOf(u)]||{}).total||0)*.15)})));
  function addStat(skill,ok){const st=S.skillStats[skill]||{total:0,correct:0};st.total++;if(ok)st.correct++;st.updated=todayKey();S.skillStats[skill]=st;S.adaptiveStats.answered++;if(ok)S.adaptiveStats.correct++;saveAdaptive()}
  function openAdaptive(){const candidates=allQuestions().sort((a,b)=>b.weight-a.weight).slice(0,Math.min(30,CU.length*3));run={items:shuf(candidates).slice(0,10),index:0,correct:0,answered:false};S.adaptiveStats.sessions++;saveAdaptive();renderAdaptive()}
  function renderAdaptive(){if(!run)return;nav('learn');$('.fab').style.display='none';const a=run;
    if(a.index>=a.items.length){const pct=Math.round(a.correct/a.items.length*100);gain(a.correct*5,false);v.innerHTML=`<div class="hr"><button class="pill-action" data-adaptive-home>← Volver</button><span class="pill">Sesión adaptativa</span></div><div class="adaptive-hero" style="text-align:center"><div style="font-size:42px">${pct>=80?'🏆':'🧠'}</div><div class="mini-label">SESIÓN COMPLETADA</div><h2>${pct>=80?'¡Buen trabajo!':'Cada error te orienta'}</h2><div style="font-size:42px;font-weight:800;margin:8px">${pct}%</div><p>${a.correct} de ${a.items.length} respuestas correctas</p><p class="m">+${a.correct*5} XP. Hemos actualizado tus estadísticas por habilidad y guardado los errores para repasarlos.</p><button class="btn" data-adaptive-start>Practicar otra sesión</button><button class="btn ghost" style="margin-top:8px" data-review-center>Abrir centro de repaso</button></div>`;run=null;return}
    const q=a.items[a.index];v.innerHTML=`<div class="hr"><button class="pill-action" data-adaptive-home>✕ Salir</button><span class="pill">${a.index+1}/${a.items.length}</span></div><div class="progress-track" style="margin-top:12px"><i style="width:${a.index/a.items.length*100}%"></i></div><div class="mini-label" style="margin-top:22px">${q.level} · ${q.skill}</div><h2 style="line-height:1.4">${q.prompt}</h2><p class="m">Sesión adaptativa: combina niveles y prioriza temas que conviene reforzar.</p>${q.options.map((o,i)=>`<button class="adaptive-answer" data-adaptive-answer="${i}">${o}</button>`).join('')}<div id="adaptive-feedback"></div>`;
  }
  function answerAdaptive(i){if(!run||run.answered)return;const q=run.items[run.index],choice=q.options[i],ok=choice===q.answer;run.answered=true;if(ok)run.correct++;addStat(q.skill,ok);
    document.querySelectorAll('[data-adaptive-answer]').forEach((b,j)=>{b.disabled=true;if(q.options[j]===q.answer)b.classList.add('correct');else if(j===i)b.classList.add('incorrect')});
    if(!ok){S.errorLog.unshift({id:Date.now()+'-'+Math.random().toString(36).slice(2,6),date:todayKey(),reviewed:false,kind:'adaptive',level:q.level,source:'Práctica adaptativa',prompt:q.prompt,answer:q.answer,chosen:choice,explanation:q.explanation});S.errorLog=S.errorLog.slice(0,100);S.adaptiveStats.missed=(S.adaptiveStats.missed||0)+1;saveAdaptive()}
    const fb=$('#adaptive-feedback');if(fb)fb.innerHTML=`<div class="glass" style="margin-top:14px"><b>${ok?'✓ Correcto':'💡 Respuesta correcta: '+q.answer}</b><p class="m">${q.explanation}</p><button class="btn" id="adaptive-next">${run.index===run.items.length-1?'Ver resultado':'Siguiente'}</button></div>`;$('#adaptive-next').onclick=()=>{run.index++;run.answered=false;renderAdaptive()};
  }
  function reviewCenter(){run=null;nav('learn');$('.fab').style.display='none';const due=Object.entries(S.review).filter(([,r])=>r.due&&r.due<=todayKey());const pending=(S.errorLog||[]).filter(e=>!e.reviewed);const skills=['Gramática','Vocabulario','Comprensión','Comunicación'];
    const dueHtml=due.length?due.map(([en,r])=>{const es=Object.values(D).flat().find(w=>w[0]===en)?.[1]||'';return `<div class="card"><div class="hr"><div><b>${en}</b><div class="m">${es}</div></div><span class="adaptive-pill">${r.level||'Repaso'}</span></div><button class="btn ghost" data-review-word="${encodeURIComponent(en)}">Practicar palabra</button></div>`}).join(''):'<div class="card"><b>¡Estás al día!</b><p class="m">No tienes palabras vencidas para repasar. Sigue practicando para crear nuevos repasos.</p></div>';
    const skillHtml=skills.map(k=>{const st=S.skillStats[k]||{total:0,correct:0},pct=st.total?Math.round(st.correct/st.total*100):0;return `<div class="skill-row"><span>${k}</span><div class="skill-track"><i style="width:${pct}%"></i></div><b>${st.total?pct+'%':'—'}</b></div>`}).join('');
    v.innerHTML=`<div class="hr"><div><div class="mini-label">Tu plan personal</div><h2>Centro de repaso</h2></div><button class="pill-action" data-adaptive-home>Volver</button></div><div class="adaptive-grid"><div class="adaptive-stat"><small class="m">Sesiones</small><b>${S.adaptiveStats.sessions||0}</b></div><div class="adaptive-stat"><small class="m">Precisión total</small><b>${S.adaptiveStats.answered?Math.round(S.adaptiveStats.correct/S.adaptiveStats.answered*100):0}%</b></div><div class="adaptive-stat"><small class="m">Palabras vencidas</small><b>${due.length}</b></div><div class="adaptive-stat"><small class="m">Errores pendientes</small><b>${pending.length}</b></div></div><div class="card"><h3>Habilidades</h3><p class="m">La precisión se calcula con tus respuestas registradas en sesiones adaptativas; todavía no equivale a una evaluación oficial.</p>${skillHtml}</div><div class="hr"><h3>Palabras para repasar</h3><span class="pill">${due.length}</span></div>${dueHtml}<div class="hr" style="margin-top:18px"><h3>Errores por revisar</h3><button class="btn ghost" data-errors="1">Abrir cuaderno (${pending.length})</button></div><p class="m">El plan adapta la práctica según tus errores y los temas que aún estás aprendiendo. Los datos se guardan localmente en este navegador.</p><button class="btn" data-adaptive-start>Empezar práctica adaptativa</button>`;
  }
  function practiceWord(encoded){const en=decodeURIComponent(encoded),found=Object.values(D).flat().find(w=>w[0]===en);if(!found)return;const old=S.review[en]||{reps:0,lapses:0};v.innerHTML=`<div class="hr"><button class="pill-action" data-review-center>← Repaso</button><span class="pill">Vocabulario</span></div><div class="adaptive-hero" style="text-align:center"><div class="mini-label">¿RECUERDAS ESTA PALABRA?</div><h2 style="font-size:34px">${found[0]}</h2><button class="btn ghost" id="show-translation">Mostrar traducción</button><p id="word-translation" hidden style="font-size:22px;font-weight:700">${found[1]}</p><p class="m">Intenta recordarla antes de revelar la respuesta.</p><div class="adaptive-grid"><button class="btn ghost" data-word-grade="0">Otra vez</button><button class="btn" data-word-grade="1">La recordé</button></div></div>`;
    $('#show-translation').onclick=()=>{$('#word-translation').hidden=false;say(found[0])};
    v.querySelectorAll('[data-word-grade]').forEach(b=>b.onclick=()=>{const ok=b.dataset.wordGrade==='1',reps=ok?Math.min(5,(old.reps||0)+1):0,days=ok?[1,3,7,14,30][Math.min(4,reps-1)]:1;S.review[en]={interval:days,reps,lapses:(old.lapses||0)+(ok?0:1),last:todayKey(),due:plusDays(days),level:S.lvl};if(!ok){S.errorLog.unshift({id:Date.now()+'',date:todayKey(),reviewed:false,kind:'vocab',level:S.lvl,source:'Repaso espaciado',prompt:found[0],answer:found[1],explanation:'Vuelve a intentar recordar la palabra sin mirar la traducción.'})}saveAdaptive();toast(ok?'¡Bien! Próximo repaso programado.':'La volveremos a mostrar pronto.');reviewCenter()});
  }
  // Add clear entry points without replacing the existing navigation or lesson system.
  const oldLearn=learn;learn=function(){oldLearn();const first=v.querySelector('.course-level');if(first&&!v.querySelector('[data-adaptive-start]'))first.insertAdjacentHTML('beforebegin',`<div class="adaptive-hero"><div class="mini-label">TU SIGUIENTE PASO</div><h3 style="margin:5px 0">Práctica adaptativa</h3><p class="m">10 preguntas que priorizan temas pendientes, errores y tu nivel de referencia.</p><div class="row" style="gap:8px;flex-wrap:wrap"><button class="btn" data-adaptive-start>Empezar práctica</button><button class="btn ghost" data-review-center>Centro de repaso</button></div></div>`)};
  const oldHome=home;home=function(){oldHome();const anchor=[...v.querySelectorAll('.card,.glass')].find(el=>el.textContent.includes('Repaso inteligente'));if(anchor&&!v.querySelector('[data-adaptive-start]'))anchor.insertAdjacentHTML('afterend',`<div class="card"><div class="hr"><div><div class="lab">Entrenamiento adaptativo</div><p class="m">Practica lo que más necesitas reforzar.</p></div><span style="font-size:26px">🧠</span></div><div class="row" style="gap:8px"><button class="btn" data-adaptive-start>Practicar</button><button class="btn ghost" data-review-center>Estadísticas</button></div></div>`)};
  document.addEventListener('click',e=>{const t=e.target.closest('[data-adaptive-start],[data-adaptive-answer],[data-adaptive-home],[data-review-center],[data-review-word]');if(!t)return;
    if(t.hasAttribute('data-adaptive-start')){e.preventDefault();e.stopImmediatePropagation();openAdaptive()}
    else if(t.dataset.adaptiveAnswer!==undefined){e.preventDefault();e.stopImmediatePropagation();answerAdaptive(Number(t.dataset.adaptiveAnswer))}
    else if(t.hasAttribute('data-adaptive-home')){e.preventDefault();e.stopImmediatePropagation();run=null;go('home')}
    else if(t.hasAttribute('data-review-center')){e.preventDefault();e.stopImmediatePropagation();reviewCenter()}
    else if(t.dataset.reviewWord){e.preventDefault();e.stopImmediatePropagation();practiceWord(t.dataset.reviewWord)}
  },true);
  // Keep the word-review buttons' labels independent from user-generated content.
})();

