/* Premium game layer: reward moments, improved theme control and accessible motion. */
(()=>{
  const root=document.documentElement, themeButton=document.querySelector('#th');
  const syncTheme=()=>{
    const light=(S.theme==='light');
    root.dataset.t=light?'light':'dark';
    if(themeButton){
      themeButton.textContent=light?'🌙':'☀️';
      themeButton.setAttribute('aria-label',light?'Cambiar a tema oscuro':'Cambiar a tema claro');
      themeButton.title=light?'Cambiar a tema oscuro':'Cambiar a tema claro';
    }
    const meta=document.querySelector('meta[name="theme-color"]');
    if(meta)meta.content=light?'#f4f5ff':'#090b18';
  };
  if(themeButton){
    themeButton.onclick=()=>{
      S.theme=S.theme==='light'?'dark':'light';
      try{localStorage.setItem('eq',JSON.stringify(S));}catch(e){}
      syncTheme();
      if(typeof toast==='function')toast(S.theme==='light'?'☀️ Tema claro activado':'🌙 Tema oscuro activado');
    };
  }
  syncTheme();

  const reward=(amount,levelUp)=>{
    document.querySelectorAll('.eq-reward,.eq-confetti').forEach(n=>n.remove());
    const reduced=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const box=document.createElement('div');
    box.className='eq-reward';
    box.setAttribute('role','status');
    box.innerHTML=`<div class="eq-reward-icon">${levelUp?'🏆':'✨'}</div><div><strong>${levelUp?'¡Subiste de nivel!':'¡Buen trabajo!'}</strong><small>+${amount} XP añadidos a tu aventura</small></div>`;
    document.body.appendChild(box);
    if(!reduced){
      const colors=['#ffd166','#68e1fd','#b6ffb0','#ff7bac','#b89cff'];
      for(let i=0;i<34;i++){
        const bit=document.createElement('i');bit.className='eq-confetti';
        bit.style.left=(Math.random()*100)+'vw';
        bit.style.background=colors[i%colors.length];
        bit.style.setProperty('--drift',((Math.random()-.5)*180)+'px');
        bit.style.animationDelay=(Math.random()*.35)+'s';
        bit.style.animationDuration=(1.1+Math.random()*.8)+'s';
        document.body.appendChild(bit);
        setTimeout(()=>bit.remove(),2300);
      }
    }
    if(levelUp){
      const hero=document.querySelector('.hero');
      if(hero){hero.classList.add('eq-levelup');setTimeout(()=>hero.classList.remove('eq-levelup'),1500);}
    }
    setTimeout(()=>box.remove(),2200);
  };
  if(typeof window.gain==='function'&&!window.gain.__eqPremiumWrapped){
    const original=window.gain;
    const wrapped=function(amount,touchIt){
      const before=Number(S.xp)||0;
      const result=original.apply(this,arguments);
      const after=Number(S.xp)||0;
      const earned=Math.max(0,after-before);
      if(earned>0)reward(earned,Math.floor(after/100)>Math.floor(before/100));
      return result;
    };
    wrapped.__eqPremiumWrapped=true;
    window.gain=wrapped;
  }

  // Animate each screen change without replacing its existing rendering logic.
  const view=document.querySelector('#v');
  if(view){
    const observer=new MutationObserver(()=>{
      view.classList.remove('view-enter');
      void view.offsetWidth;
      view.classList.add('view-enter');
    });
    observer.observe(view,{childList:true});
  }
})();

